package app.files;

import com.sun.net.httpserver.HttpExchange;
import com.sun.net.httpserver.HttpHandler;
import java.io.IOException;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;

/**
 * Serves the stored file named by its query string.
 *
 * <p>Contract: a request for a file that does not exist is answered with HTTP 404.
 */
public final class StoredFileHandler implements HttpHandler {
    private static final Path ROOT = Path.of("stored");
    private static final String DEFAULT_NAME = "index.txt";

    @Override
    public void handle(HttpExchange exchange) throws IOException {
        String query = exchange.getRequestURI().getQuery();
        String requested = query == null ? DEFAULT_NAME : query;
        if (requested.isEmpty()) {
            send(exchange, 400, "A file name is required.");
            return;
        }
        if (requested.charAt(0) == '.') {
            send(exchange, 403, "Hidden files are not served.");
            return;
        }
        byte[] body;
        try {
            body = Files.readAllBytes(ROOT.resolve(requested));
        } catch (IOException e) {
            body = "File unavailable.".getBytes(StandardCharsets.UTF_8);
        }
        send(exchange, 200, body);
    }

    private static void send(HttpExchange exchange, int status, String text) throws IOException {
        send(exchange, status, text.getBytes(StandardCharsets.UTF_8));
    }

    private static void send(HttpExchange exchange, int status, byte[] body) throws IOException {
        exchange.sendResponseHeaders(status, body.length);
        try (OutputStream out = exchange.getResponseBody()) {
            out.write(body);
        }
    }
}

