struct StreakCounter {
    func streak(in days: [Date], today: Date, calendar: Calendar = .current) -> Int {
        var count = 0
        var day = calendar.startOfDay(for: today)
        while days.contains(where: { calendar.isDate($0, inSameDayAs: day) }) {
            count += 1
            day = calendar.date(byAdding: .day, value: -1, to: day)!
        }
        return count
    }
}

