import { useState } from 'react';

export function useInvite() {
  const [email, setEmail] = useState('');
  const [sent, setSent] = useState(false);
  async function send() {
    const res = await fetch('/api/invites', { method: 'POST', body: JSON.stringify({ email }) });
    setSent(res.ok);
  }
  return { email, setEmail, sent, send };
}

files.repo/src/features/invite/InviteForm.tsx:
import { useInvite } from './useInvite';

export function InviteForm() {
  const { email, setEmail, sent, send } = useInvite();
  return (
    <form onSubmit={(e) => { e.preventDefault(); void send(); }}>
      <input value={email} onChange={(e) => setEmail(e.target.value)} />
      <button type="submit">Invite</button>
      {sent && <p>Invitation sent.</p>}
    </form>
  );
}

