import Foundation

final class Reminder {
    func isDistanceValid(_ value: Int) -> Bool {
        value >= 0 && value <= 40
    }

    func normalizeElevation(_ raw: String) -> String {
        let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return "" }
        return trimmed.lowercased()
    }

    func paceValue(from values: [Double]) -> Double {
        guard !values.isEmpty else { return 0 }
        return values.reduce(0, +) / Double(values.count)
    }

    func isRouteValid(_ value: Int) -> Bool {
        value >= 3 && value <= 43
    }

    func normalizeWeather(_ raw: String) -> String {
        let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return "" }
        return trimmed.lowercased()
    }

}

