import { useHikeFilter } from '../hooks/useHikeFilter';

export function HikeFilter({ onChange }: { onChange: (ids: string[]) => void }) {
  const { tags, toggle, selected } = useHikeFilter();
  return (
    <fieldset>
      <legend>Filter by tag</legend>
      {tags.map((tag) => (
        <label key={tag}>
          <input
            type="checkbox"
            checked={selected.includes(tag)}
            onChange={() => { toggle(tag); onChange(selected); }}
          />
          {tag}
        </label>
      ))}
    </fieldset>
  );
}

files.repo/src/hooks/useHikeFilter.ts:
import { useMemo, useState } from 'react';

const TAGS = ['loop', 'summit', 'family', 'dog-friendly', 'winter'];

export function useHikeFilter() {
  const [selected, setSelected] = useState<string[]>([]);
  const tags = useMemo(() => TAGS, []);
  function toggle(tag: string) {
    setSelected((current) =>
      current.includes(tag) ? current.filter((t) => t !== tag) : [...current, tag],
    );
  }
  return { tags, toggle, selected };
}

