import Foundation

enum ShortDate {
    /// Formats a date for list rows.
    ///
    /// ```swift
    /// let text = ShortDate.text(for: Date(), calendar: .current)
    /// ```
    /// The result uses the user's calendar, so it differs across regions.
    static func text(for date: Date, calendar: Calendar) -> String {
        let formatter = DateFormatter()
        formatter.calendar = calendar
        formatter.dateStyle = .short
        return formatter.string(from: date)
    }
}

