import json
from pathlib import Path


class SettingsError(Exception):
    pass


def load_settings(path: Path) -> "Settings":
    """Read settings from ``path``.

    A missing file means the app has not run before, so the defaults apply.
    A file that exists but is not valid JSON raises ``SettingsError``.
    """
    try:
        raw = path.read_text(encoding="utf-8")
    except FileNotFoundError:
        return Settings.defaults()
    try:
        return Settings.from_dict(json.loads(raw))
    except json.JSONDecodeError as exc:
        raise SettingsError(f"{path} is not valid JSON") from exc

