import { useEffect, useState } from "react";

export function ProfileCard({ id }: { id: string }) {
  const [name, setName] = useState("");
  useEffect(() => {
    fetch(`/api/profiles/${id}`)
      .then((response) => response.json())
      .then((profile) => setName(profile.name));
  }, [id]);
  return <p>{name}</p>;
}

