import Foundation

struct Plant: Identifiable, Codable {
    let id: UUID
    let name: String
    let wateringIntervalDays: Int
}

@MainActor @Observable
final class PlantStore {
    private(set) var plants: [Plant] = []

    func add(name: String, wateringIntervalDays: Int) {
        plants.append(Plant(id: UUID(), name: name, wateringIntervalDays: wateringIntervalDays))
    }
}

